DROP TABLE IF EXISTS database_doktrin_keterbukaan;
CREATE TABLE IF NOT EXISTS database_doktrin_keterbukaan (
    id INT PRIMARY KEY,
    country VARCHAR(100) NOT NULL,
    name_en VARCHAR(100) NOT NULL,
    ideology VARCHAR(100) NOT NULL,
    speech_score INT NOT NULL,
    religion_score INT NOT NULL,
    demo_score INT NOT NULL,
    transparency_score INT NOT NULL,
    media_score INT NOT NULL,
    internet_score INT NOT NULL,
    border_score INT NOT NULL,
    trade_score INT NOT NULL,
    diplomacy_score INT NOT NULL,
    openness_index INT NOT NULL
);

INSERT INTO database_doktrin_keterbukaan (
